// VERSION and PRECACHE are generated by build.mjs. No library code is embedded.
const CACHE = `searchlock-${VERSION}`;
let cachePromise;
const currentCache = () => (cachePromise ??= caches.open(CACHE));
const clientVersions = new Map();
const scope = self.registration.scope;
const owns = (name) =>
  name.startsWith("searchlock-") || (name.startsWith("workbox-precache-") && name.endsWith(scope));

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      try {
        const cache = await currentCache();
        await cache.addAll(PRECACHE.map((url) => new Request(url, { cache: "reload" })));
        await self.skipWaiting();
      } catch (error) {
        await caches.delete(CACHE);
        throw error;
      }
    })(),
  );
});

async function cleanup() {
  const clients = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  // Old tabs, including pre-migration Workbox tabs, still need their old chunks.
  if (
    clients.some(
      (client) => client.url.startsWith(scope) && clientVersions.get(client.id) !== VERSION,
    )
  )
    return;
  await Promise.all(
    (await caches.keys())
      .filter((name) => owns(name) && name !== CACHE)
      .map((name) => caches.delete(name)),
  );
}

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      await self.clients.claim();
      await cleanup();
    })(),
  );
});

self.addEventListener("message", (event) => {
  if (event.data?.type !== "CLIENT_VERSION" || !event.source?.id) return;
  clientVersions.set(event.source.id, event.data.version);
  event.waitUntil(cleanup());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET" || !request.url.startsWith(scope)) return;
  event.respondWith(
    (async () => {
      const cache = await currentCache();
      const navigation = request.mode === "navigate";
      const key = navigation ? new URL("index.html", scope).href : request;
      const response = await cache.match(key);
      if (response) return response;
      if (!navigation) {
        for (const name of (await caches.keys()).filter(owns)) {
          if (name === CACHE) continue;
          const old = await (await caches.open(name)).match(request);
          if (old) return old;
        }
      }
      return fetch(request);
    })(),
  );
});
